package darksafe

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// 本文件回归保障序列身份在“分隔字符”上的正确性。冒号、分号、等号、逗号和花括号
// 经常被用作标签文本表示（如 SeriesRef.String 的 name{k=v,...} 与身份签名内部拼接）
// 的边界，但它们出现在指标名、标签键或标签值里时只是用户数据：身份只由指标名与
// JSON 解析后的完整标签集合决定，标签书写顺序与同一字符的合法 JSON 转义写法都不
// 参与身份判断。普通标签的重复与冲突已在 metrics_test.go 覆盖，这里专补在文本表示
// 中容易互相混淆的合法输入。

// labelsOf 按指标名与完整标签集合在写入快照中定位序列，返回其标签与采样点。
func labelsOf(t *testing.T, res *BatchResult, name string, labels map[string]string) (map[string]string, []Point) {
	t.Helper()
	i := findViewIndex(t, res, name, labels)
	return res.Series[i].Labels, res.Series[i].Points
}

// queryOne 要求查询恰好命中一个序列并返回该条目。
func queryOne(t *testing.T, store *MetricStore, line string) QuerySeries {
	t.Helper()
	res := mustQuery(t, store, line)
	if len(res.Series) != 1 {
		t.Fatalf("query %s: got %d series %+v, want exactly 1", line, len(res.Series), res.Series)
	}
	return res.Series[0]
}

// sample 构造一条采样点 JSON 文本；labels 为 nil 时省略 labels 字段。
// 名称与标签经 encoding/json 转义，因此调用方可以直接给含分隔字符与空格的原始文本。
func sample(name string, ts int64, value any, labels map[string]string) string {
	var b strings.Builder
	n, _ := json.Marshal(name)
	fmt.Fprintf(&b, `{"name":%s,"timestamp":%d,"value":%v`, n, ts, value)
	if labels != nil {
		b.WriteString(`,"labels":`)
		b.WriteString(jsonLabels(labels))
	}
	b.WriteByte('}')
	return b.String()
}

// jsonLabels 把标签集合编码为 JSON 对象文本（Go 按键排序输出，身份与顺序无关）。
func jsonLabels(labels map[string]string) string {
	b, _ := json.Marshal(labels)
	return string(b)
}

// jsonString 把单个字符串编码为 JSON 字符串文本。
func jsonString(s string) string {
	b, _ := json.Marshal(s)
	return string(b)
}

// uescape 返回 JSON 的 \uXXXX 转义文本（反斜杠以 rune 构造，避免与源码转义混淆）。
func uescape(hex string) string {
	return string(rune(92)) + "u" + hex
}

// withJSONEscapes 把模板中的占位符替换为对应字符的 JSON \uXXXX 转义书写，
// 用于以“转义写法”提交与直接书写完全相同的真实文本。
func withJSONEscapes(tmpl string) string {
	return strings.NewReplacer(
		"#CO#", uescape("003a"), // ':'
		"#SC#", uescape("003b"), // ';'
		"#LB#", uescape("007b"), // '{'
		"#RB#", uescape("007d"), // '}'
	).Replace(tmpl)
}

// queryLabels 构造按标签子集查询的 JSON 对象文本。
func queryLabels(name string, start, end int64, labels map[string]string) string {
	return `{"op":"query","name":` + jsonString(name) +
		fmt.Sprintf(`,"start":%d,"end":%d,"labels":`, start, end) + jsonLabels(labels) + `}`
}

// TestDelimitersInLabelValueStayDistinct 是核心回归：一个标签值看起来像另外两个
// 标签（"b=2"），另一个标签值看起来包含标签对分隔符（"b=2,c=3"）。冒号、分号、
// 等号、逗号和花括号在值里都是普通字符，不能被当成键值或标签之间的边界。
func TestDelimitersInLabelValueStayDistinct(t *testing.T) {
	store := NewMetricStore()
	// 三条序列在同一时间戳写入相同数值 1，但完整标签集合不同，必须分别新增。
	// single:  一个标签，其值文本上像 "b=2"。
	// pair:    两个标签，文本拼起来恰好也是 a=1,b=2。
	// spill:   一个标签，其值文本上像两个标签 "b=2,c=3"。
	res := mustOK(t, store, `[
		{"name":"m","timestamp":10,"value":1,"labels":{"a":"b=2"}},
		{"name":"m","timestamp":10,"value":1,"labels":{"a":"1","b":"2"}},
		{"name":"m","timestamp":10,"value":1,"labels":{"a":"b=2,c=3"}}
	]`)
	if res.Added != 3 || res.Duplicates != 0 || len(res.Series) != 3 {
		t.Fatalf("look-alike label text must create 3 series, got %+v", res)
	}

	// 成功结果保留各自完整的名称、标签与采样点（值里的等号/逗号原样保留）。
	single := map[string]string{"a": "b=2"}
	pair := map[string]string{"a": "1", "b": "2"}
	spill := map[string]string{"a": "b=2,c=3"}
	for _, want := range []struct {
		labels map[string]string
		point  Point
	}{
		{single, Point{Timestamp: 10, Value: 1}},
		{pair, Point{Timestamp: 10, Value: 1}},
		{spill, Point{Timestamp: 10, Value: 1}},
	} {
		gotLabels, gotPoints := labelsOf(t, res, "m", want.labels)
		if !reflect.DeepEqual(gotLabels, want.labels) {
			t.Fatalf("labels not preserved verbatim: got %v want %v", gotLabels, want.labels)
		}
		if len(gotPoints) != 1 || gotPoints[0] != want.point {
			t.Fatalf("points for %v = %+v, want %+v", want.labels, gotPoints, want.point)
		}
	}

	// 子集查询各匹配各的序列：标签文本里的 "b=2" 片段不能被当成另一个标签 b。
	if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"b=2"}}`); !reflect.DeepEqual(got.Labels, single) || got.Count != 1 || got.Average != 1 {
		t.Fatalf("a=b=2 query = %+v, want the single-label series", got)
	}
	if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"b":"2"}}`); !reflect.DeepEqual(got.Labels, pair) || got.Count != 1 {
		t.Fatalf("b=2 subset must match only the real two-label series, got %+v", got)
	}
	if len(mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"c":"3"}}`).Series) != 0 {
		t.Fatalf("value fragment c=3 must not be read as a label")
	}
	// 全量查询仍是三条独立序列，各自一个点，点数与均值互不混淆。
	all := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":100}`)
	if len(all.Series) != 3 {
		t.Fatalf("full query = %+v, want 3 separate series", all.Series)
	}
	for _, s := range all.Series {
		if s.Count != 1 || s.Average != 1 {
			t.Fatalf("series %v must keep its own single point, got count=%d average=%v", s.Labels, s.Count, s.Average)
		}
	}

	// 三条序列写入彼此不同的数值也不冲突；各序列各取自己的均值。
	mustOK(t, store, `[{"name":"m","timestamp":20,"value":5,"labels":{"a":"b=2"}}]`)
	mustOK(t, store, `[{"name":"m","timestamp":20,"value":7,"labels":{"a":"1","b":"2"}}]`)
	mustOK(t, store, `[{"name":"m","timestamp":20,"value":9,"labels":{"a":"b=2,c=3"}}]`)
	if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"b=2"}}`); got.Count != 2 || got.Average != 3 {
		t.Fatalf("single series average = count %d avg %v, want 2 points avg 3", got.Count, got.Average)
	}
	if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"1","b":"2"}}`); got.Count != 2 || got.Average != 4 {
		t.Fatalf("pair series average = count %d avg %v, want 2 points avg 4", got.Count, got.Average)
	}
	if got := queryOne(t, store, `{"op":"query","name":"m","start":0,"end":100,"labels":{"a":"b=2,c=3"}}`); got.Count != 2 || got.Average != 5 {
		t.Fatalf("spill series average = count %d avg %v, want 2 points avg 5", got.Count, got.Average)
	}
}

// TestDelimitersAcrossKeysValuesAndNames 把全部分隔字符放进标签键与标签值，
// 并让指标名本身也含分隔字符；任何字符都不得充当边界导致身份合并。
func TestDelimitersAcrossKeysValuesAndNames(t *testing.T) {
	store := NewMetricStore()
	tricky := []string{":", ";", "=", ",", "{", "}", "{=", "=}", ",;", ":=;{}", "x{y=z,w}"}
	batch := make([]string, 0, 2*len(tricky)+2)
	// 同名、标签键含分隔字符：每个键一条独立序列。
	for i, k := range tricky {
		batch = append(batch, sample("cpu", 100, i+1, map[string]string{k: "plain"}))
	}
	// 标签值含分隔字符的一组。
	for i, v := range tricky {
		batch = append(batch, sample("cpu", 100, i+100, map[string]string{"k": v}))
	}
	// 指标名含分隔字符，与名为 cpu 的序列区分开。
	batch = append(batch,
		sample("cpu:rate{host=a}", 100, 7, nil),
		sample("cpu:rate{host=a", 100, 8, nil), // 少一个花括号也是另一个名字
	)
	res := mustOK(t, store, "["+strings.Join(batch, ",")+"]")
	if want := 2*len(tricky) + 2; res.Added != want || len(res.Series) != want {
		t.Fatalf("delimiter-heavy identities: added=%d series=%d, want %d", res.Added, len(res.Series), want)
	}

	// 键含分号/冒号的标签仍能精确子集查询。
	for _, k := range tricky {
		line := queryLabels("cpu", 0, 200, map[string]string{k: "plain"})
		got := queryOne(t, store, line)
		if v, ok := got.Labels[k]; !ok || v != "plain" || len(got.Labels) != 1 {
			t.Fatalf("delimiter key %q not matched verbatim: %+v", k, got)
		}
	}
	// 值含花括号/逗号等的标签同样原样匹配。
	got := queryOne(t, store, queryLabels("cpu", 0, 200, map[string]string{"k": "x{y=z,w}"}))
	if got.Labels["k"] != "x{y=z,w}" || got.Average != float64(100+len(tricky)-1) {
		t.Fatalf("delimiter value not preserved/matched: %+v", got)
	}
	// 指标名中的分隔字符是名字的一部分：两个花括号形态不同的名字各自独立。
	for _, c := range []struct {
		name string
		val  float64
	}{
		{"cpu:rate{host=a}", 7},
		{"cpu:rate{host=a", 8},
	} {
		line := `{"op":"query","name":` + jsonString(c.name) + `,"start":0,"end":200}`
		s := queryOne(t, store, line)
		if s.Name != c.name || s.Average != c.val || len(s.Labels) != 0 {
			t.Fatalf("delimiter-in-name query = %+v, want name %q value %v", s, c.name, c.val)
		}
	}
}

// TestSameConcatenatedTextDifferentKeySplit 针对长度前缀身份签名自身的边界：
// 若把键值直接拼接，冒号/分号会被当成边界，使不同的键值划分产生同一段文本。
// 这些输入在朴素拼接表示下两两碰撞，但必须是四条不同序列：
//
//	A {"a":"b:c"} 与 B {"a:b":"c"}：朴素拼接都是 a:b:c
//	C {"a":"b;x:y"} 与 D {"a":"b","x":"y"}（值看起来像两个标签）：朴素拼接都是 a:b;x:y
func TestSameConcatenatedTextDifferentKeySplit(t *testing.T) {
	store := NewMetricStore()
	res := mustOK(t, store, `[
		{"name":"m","timestamp":1,"value":1,"labels":{"a":"b:c"}},
		{"name":"m","timestamp":1,"value":2,"labels":{"a:b":"c"}},
		{"name":"m","timestamp":1,"value":3,"labels":{"a":"b;x:y"}},
		{"name":"m","timestamp":1,"value":4,"labels":{"a":"b","x":"y"}}
	]`)
	if res.Added != 4 || len(res.Series) != 4 {
		t.Fatalf("same concatenated text, different key/value splits must stay distinct: %+v", res)
	}
	want := []map[string]string{
		{"a": "b:c"},
		{"a:b": "c"},
		{"a": "b;x:y"},
		{"a": "b", "x": "y"},
	}
	all := mustQuery(t, store, `{"op":"query","name":"m","start":0,"end":10}`)
	if len(all.Series) != 4 {
		t.Fatalf("query = %+v, want 4 series", all.Series)
	}
	for i, labels := range want {
		found := false
		for _, s := range all.Series {
			if reflect.DeepEqual(s.Labels, labels) {
				found = true
				if s.Count != 1 || s.Average != float64(i+1) {
					t.Fatalf("series %v must keep its own point, got count=%d average=%v",
						labels, s.Count, s.Average)
				}
			}
		}
		if !found {
			t.Fatalf("series %v missing from query result %+v (case %d)", labels, all.Series, i)
		}
	}
	// 子集匹配按真实键值对：冒号在键里与在值里是不同的标签。
	if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"a:b": "c"})); got.Average != 2 {
		t.Fatalf("key-with-colon label match = %+v, want value 2", got)
	}
	if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"a": "b:c"})); got.Average != 1 {
		t.Fatalf("value-with-colon label match = %+v, want value 1", got)
	}
	// "x=y" 只真实存在于两标签序列；单标签值里的 "x:y" 片段不产生标签 x。
	if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"x": "y"})); got.Average != 4 {
		t.Fatalf("x=y must match only the real two-label series, got %+v", got)
	}
}

// TestDelimiterIdentityDuplicateAcrossOrderAndEscapes：身份确实相同时，调换标签
// 书写顺序、用合法 JSON 转义书写同一个分隔字符，再次提交相同时间戳与数值都计为
// 重复，不新增点；成功结果里字符仍是解析后的真实文本（只有一个真实冒号）。
func TestDelimiterIdentityDuplicateAcrossOrderAndEscapes(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"m:x","timestamp":5,"value":4,"labels":{"a:1":"x;y","b":"{z}"}}]`)
	// 标签顺序调换；名字里的冒号、键里的冒号、值里的分号与花括号改用 JSON
	// #XX# 占位符对应的 \uXXXX 转义书写，解析后的真实文本必须与首条完全一致。
	resubmit := withJSONEscapes(
		`[{"name":"m#CO#x","timestamp":5,"value":4.0,"labels":{"b":"#LB#z#RB#","a#CO#1":"x#SC#y"}}]`)
	res := mustOK(t, store, resubmit)
	if res.Added != 0 || res.Duplicates != 1 || len(res.Series) != 1 {
		t.Fatalf("escaped/reordered resubmit must be one duplicate, got %+v", res)
	}
	got := res.Series[0]
	wantLabels := map[string]string{"a:1": "x;y", "b": "{z}"}
	if got.Name != "m:x" || !reflect.DeepEqual(got.Labels, wantLabels) {
		t.Fatalf("identity must resolve to parsed text, got name=%q labels=%v", got.Name, got.Labels)
	}
	if pts := got.Points; len(pts) != 1 || pts[0] != (Point{Timestamp: 5, Value: 4}) {
		t.Fatalf("duplicate must add no point, got %+v", pts)
	}

	// 同一时间戳换成不同数值（同样以转义+乱序书写身份）：拒绝整批，冲突指向
	// JSON 解析后的真实完整序列、时间戳以及已有值与提交值。
	conflictLine := withJSONEscapes(
		`[{"name":"m#CO#x","timestamp":5,"value":40,"labels":{"b":"#LB#z#RB#","a#CO#1":"x#SC#y"}}]`)
	lerr := mustFail(t, store, conflictLine)
	if lerr.Index != 1 || lerr.Conflict == nil {
		t.Fatalf("expected conflict, got %+v", lerr)
	}
	c := lerr.Conflict
	if c.Series.Name != "m:x" || !reflect.DeepEqual(c.Series.Labels, wantLabels) ||
		c.Timestamp != 5 || c.Existing != 4 || c.Submitted != 40 {
		t.Fatalf("conflict must name real identity/values, got %+v", c)
	}
	// 冲突原因文本里的序列按 name{k=v,...} 呈现；该表示对含分隔字符的数据有歧义
	// （单标签 a=b=2 与两标签 a=1,b=2 的渲染相同），因此冲突的权威归属以结构化
	// conflict.series 为准。这里锁定现有文本格式不被意外改动。
	if !strings.HasPrefix(lerr.Error, "conflict: series m:x{a:1=x;y,b={z}} at timestamp 5 already has value 4, submitted 40") {
		t.Fatalf("conflict message = %q", lerr.Error)
	}
	// 原采样点保持不变。
	snap := mustOK(t, store, `[]`)
	if pts := snap.Series[0].Points; len(pts) != 1 || pts[0].Value != 4 {
		t.Fatalf("rejected batch must leave original point intact, got %+v", pts)
	}
}

// TestLookAlikeIdentitiesDoNotConflict：两条文本渲染完全相同的不同序列，在同一
// 时间戳分别提交不同数值不得互相冲突；随后对其中一条再改值才冲突，且冲突报告的
// 是结构化的真实完整标签集合，而不是有歧义的渲染文本。
func TestLookAlikeIdentitiesDoNotConflict(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":1,"labels":{"a":"b=2"}}]`)
	// 单标签 a="b=2" 与两标签 a=1,b=2 的 String() 都是 cpu{a=b=2}，但身份不同。
	res := mustOK(t, store, `[{"name":"cpu","timestamp":1,"value":2,"labels":{"a":"1","b":"2"}}]`)
	if res.Added != 1 || res.Duplicates != 0 || len(res.Series) != 2 {
		t.Fatalf("look-alike identities with different values must both be added, got %+v", res)
	}
	// 对单标签序列提交不同值：冲突，结构化标签只有一个键且值原样为 "b=2"。
	lerr := mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"b=2"}}]`)
	if lerr.Conflict == nil || lerr.Conflict.Existing != 1 || lerr.Conflict.Submitted != 9 {
		t.Fatalf("single-label conflict values wrong: %+v", lerr.Conflict)
	}
	if labels := lerr.Conflict.Series.Labels; len(labels) != 1 || labels["a"] != "b=2" {
		t.Fatalf("conflict must name real single-label identity, got %v", labels)
	}
	// 对两标签序列提交不同值同样冲突，结构化标签是两个键。
	lerr = mustFail(t, store, `[{"name":"cpu","timestamp":1,"value":9,"labels":{"a":"1","b":"2"}}]`)
	if lerr.Conflict == nil || lerr.Conflict.Existing != 2 {
		t.Fatalf("two-label conflict values wrong: %+v", lerr.Conflict)
	}
	if labels := lerr.Conflict.Series.Labels; len(labels) != 2 || labels["a"] != "1" || labels["b"] != "2" {
		t.Fatalf("conflict must name real two-label identity, got %v", labels)
	}
	// 两条序列原有采样点都保持各自的值，全量查询仍返回两条独立序列。
	full := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":10}`)
	if len(full.Series) != 2 {
		t.Fatalf("full cpu query = %+v, want 2 series", full.Series)
	}
	for _, s := range full.Series {
		if s.Count != 1 {
			t.Fatalf("series %v must keep its own point, got count=%d", s.Labels, s.Count)
		}
	}
}

// TestWhitespaceInIdentityPreservedVerbatim：名称、标签键和值中的合法空格原样
// 保留，不能通过去空格把不同输入合并为同一序列。
func TestWhitespaceInIdentityPreservedVerbatim(t *testing.T) {
	store := NewMetricStore()
	res := mustOK(t, store, `[
		{"name":"m ","timestamp":1,"value":1,"labels":{"k ":"v"}},
		{"name":"m","timestamp":1,"value":2,"labels":{"k":"v"}},
		{"name":"m","timestamp":1,"value":3,"labels":{"k":" v"}},
		{"name":"m","timestamp":1,"value":4,"labels":{"k":"v "}},
		{"name":"m","timestamp":1,"value":5,"labels":{" k":"v"}}
	]`)
	if res.Added != 5 || len(res.Series) != 5 {
		t.Fatalf("whitespace variants must be 5 distinct series, got added=%d series=%d", res.Added, len(res.Series))
	}
	cases := []struct {
		name   string
		labels map[string]string
		value  float64
	}{
		{"m ", map[string]string{"k ": "v"}, 1},
		{"m", map[string]string{"k": "v"}, 2},
		{"m", map[string]string{"k": " v"}, 3},
		{"m", map[string]string{"k": "v "}, 4},
		{"m", map[string]string{" k": "v"}, 5},
	}
	for i, c := range cases {
		var line string
		if c.name == "m" {
			line = queryLabels("m", 0, 10, c.labels)
		} else {
			line = `{"op":"query","name":` + jsonString(c.name) + `,"start":0,"end":10,"labels":` + jsonLabels(c.labels) + `}`
		}
		got := queryOne(t, store, line)
		if got.Name != c.name || !reflect.DeepEqual(got.Labels, c.labels) || got.Average != c.value {
			t.Fatalf("whitespace case %d: got %+v, want name=%q labels=%v value=%v", i, got, c.name, c.labels, c.value)
		}
	}
	// 省略标签与空标签对象同一身份；缺标签与标签存在且值为空串仍是不同身份，
	// 即使标签键周围带有合法空格。
	mustOK(t, store, `[{"name":"n","timestamp":1,"value":1}]`)
	if dup := mustOK(t, store, `[{"name":"n","timestamp":1,"value":1.0,"labels":{}}]`); dup.Added != 0 || dup.Duplicates != 1 {
		t.Fatalf("omitted vs empty labels must be the same series, got %+v", dup)
	}
	if added := mustOK(t, store, `[{"name":"n","timestamp":1,"value":2,"labels":{" z ":""}}]`); added.Added != 1 {
		t.Fatalf("missing label differs from present empty value, added = %d", added.Added)
	}
	// 快照中 n 现在有两条独立序列：无标签与带空值标签（连同 m 的五条共七条）。
	nSeries := 0
	for _, v := range mustOK(t, store, `[]`).Series {
		if v.Name == "n" {
			nSeries++
		}
	}
	if nSeries != 2 {
		t.Fatalf("metric n must have 2 distinct series, got %d", nSeries)
	}
	got := queryOne(t, store, queryLabels("n", 0, 10, map[string]string{" z ": ""}))
	if len(got.Labels) != 1 || got.Labels[" z "] != "" || got.Average != 2 {
		t.Fatalf("spaced-key empty-value label not preserved: %+v", got)
	}
}

// TestDelimiterLabelSubsetMatching：子集匹配按真实键值对进行，值里的分隔符既不会
// 制造额外的匹配标签，也不会让需要的标签匹配失败；不同序列的点不混合。
func TestDelimiterLabelSubsetMatching(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"m","timestamp":1,"value":10,"labels":{"a":"x","b":"y=z"}},
		{"name":"m","timestamp":1,"value":20,"labels":{"a":"x","b":"q"}},
		{"name":"m","timestamp":1,"value":30,"labels":{"a":"x","b":"y=z","c":"d,e"}}
	]`)
	// a=x 子集命中三条，各自独立返回自己的点与均值。
	res := mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"a": "x"}))
	if len(res.Series) != 3 {
		t.Fatalf("a=x subset = %+v, want 3 series", res.Series)
	}
	// b="y=z" 只命中真实拥有该键值的两条（含带额外标签 c 的一条），不命中 b=q。
	res = mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"b": "y=z"}))
	if len(res.Series) != 2 {
		t.Fatalf("b=y=z subset = %+v, want 2 series", res.Series)
	}
	wantAvgs := map[int]bool{10: false, 30: false}
	for _, s := range res.Series {
		if s.Count != 1 {
			t.Fatalf("matched series %v must report its own single point, got count=%d", s.Labels, s.Count)
		}
		if _, ok := wantAvgs[int(s.Average)]; !ok {
			t.Fatalf("unexpected average %v from %v", s.Average, s.Labels)
		}
		wantAvgs[int(s.Average)] = true
	}
	for v, seen := range wantAvgs {
		if !seen {
			t.Fatalf("series with average %d was not matched separately", v)
		}
	}
	// 查询值里写逗号文本是完整值比较：只有值恰好为 "d,e" 的标签能匹配。
	if got := queryOne(t, store, queryLabels("m", 0, 10, map[string]string{"c": "d,e"})); got.Average != 30 {
		t.Fatalf("comma-in-value subset = %+v, want average 30", got)
	}
	if len(mustQuery(t, store, queryLabels("m", 0, 10, map[string]string{"d": "e"})).Series) != 0 {
		t.Fatalf("value fragment d,e must not be split into label d=e")
	}
}

package main

import (
	"bytes"
	"reflect"
	"strings"
	"testing"
)

// 本文件在命令行端到端层面回归保障序列身份：标签键、标签值与指标名中的
// 冒号、分号、等号、逗号和花括号都是用户数据，不能被当成键值或标签边界。
// 经 stdin 写入、快照与查询输出（JSON 真实文本）后，混淆形态的合法输入仍各自
// 归属独立序列；成功/失败结果格式与现有 ingest 输出保持兼容。

// findWireSeries 在结果 JSON（写入快照或查询）里按指标名与完整标签集合定位序列。
func findWireSeries(t *testing.T, arr []interface{}, name string, labels map[string]interface{}) map[string]interface{} {
	t.Helper()
	for _, item := range arr {
		s := item.(map[string]interface{})
		if s["name"] == name && reflect.DeepEqual(s["labels"], labels) {
			return s
		}
	}
	t.Fatalf("series %s %v not found in %v", name, labels, arr)
	return nil
}

// jsonBackslashEscape 以 rune 构造反斜杠，生成 \uXXXX 形态的 JSON 转义文本。
func jsonBackslashEscape(hex string) string {
	return string(rune(92)) + "u" + hex
}

func TestRunIngestDelimiterCharactersAreUserData(t *testing.T) {
	// 行 1：五条序列都在时间戳 1000 写入相同数值 1，但身份互不相同：
	//   cpu {"a":"1","b":"2"}        两个标签
	//   cpu {"a":"b=2"}              一个标签，值看起来像两个标签
	//   cpu {"a":"b=2,c=3"}          一个标签，值看起来像三个标签
	//   cpu {"a:b":"c;d"}            键与值都含分隔字符
	//   cpu:total{x=1}（无标签）      指标名本身含冒号、等号和花括号
	lines := []string{
		// 行 1：五条序列都在时间戳 1000 写入相同数值 1，但身份互不相同：
		//   cpu {"a":"1","b":"2"}   两个标签
		//   cpu {"a":"b=2"}         一个标签，值看起来像两个标签
		//   cpu {"a":"b=2,c=3"}     一个标签，值看起来像三个标签
		//   cpu {"a:b":"c;d"}       键与值都含分隔字符
		//   cpu:total{x=1}（无标签） 指标名本身含冒号、等号和花括号
		`[{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"1","b":"2"}},` +
			`{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"b=2"}},` +
			`{"name":"cpu","timestamp":1000,"value":1,"labels":{"a":"b=2,c=3"}},` +
			`{"name":"cpu","timestamp":1000,"value":1,"labels":{"a:b":"c;d"}},` +
			`{"name":"cpu:total{x=1}","timestamp":1000,"value":1}]`,
		// 行 2：全部身份再次提交同点同值。标签书写顺序打乱，键里的冒号与值里的
		// 分号改用 \uXXXX 转义书写，指标名中的冒号同样转义——仍全部是重复。
		`[{"name":"cpu","timestamp":1000,"value":1.0,"labels":{"b":"2","a":"1"}},` +
			`{"name":"cpu","timestamp":1000,"value":1.0,"labels":{"a":"b=2"}},` +
			`{"name":"cpu","timestamp":1000,"value":1.0,"labels":{"a":"b=2,c=3"}},` +
			`{"name":"cpu","timestamp":1000,"value":1.0,"labels":{"a#CO#b":"c#SC#d"}},` +
			`{"name":"cpu#CO#total{x=1}","timestamp":1000,"value":1.0}]`,
		// 行 3：第一个点是新增（时间戳 2000），第二个点与既有数据冲突：整批回滚。
		`[{"name":"cpu","timestamp":2000,"value":5,"labels":{"a":"b=2"}},` +
			`{"name":"cpu","timestamp":1000,"value":9,"labels":{"a":"1","b":"2"}}]`,
		// 行 4：省略标签，查 cpu 全部四条序列，各自一个点，互不混合。
		`{"op":"query","name":"cpu","start":0,"end":3000}`,
		// 行 5：值里的 "b=2" 是完整值，只命中单标签序列。
		`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"a":"b=2"}}`,
		// 行 6：真实存在的标签 b 只命中两标签序列，不命中值里写着 b=2 的单标签序列。
		`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"b":"2"}}`,
		// 行 7：值片段 c=3 不能被当成标签 c。
		`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"c":"3"}}`,
		// 行 8：键与值中的冒号、分号原样匹配。
		`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"a:b":"c;d"}}`,
		// 行 9：指标名中的分隔字符是名字的一部分。
		`{"op":"query","name":"cpu:total{x=1}","start":0,"end":3000}`,
	}
	input := strings.NewReplacer("#CO#", jsonBackslashEscape("003a"), "#SC#", jsonBackslashEscape("003b")).
		Replace(strings.Join(lines, "\n"))

	var out bytes.Buffer
	code := runIngest(strings.NewReader(input), &out)
	if code == 0 {
		t.Fatalf("exit code = 0, want non-zero because line 3 conflicted")
	}
	got := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
	if len(got) != 9 {
		t.Fatalf("got %d output lines, want 9 (2 ok writes, 1 error, 6 queries): %v", len(got), got)
	}

	// 行 1：五条序列分别新增，快照中的标签是解析后的真实文本。
	first := decodeResultLine(t, got[0])
	if first["status"] != "ok" || first["added"].(float64) != 5 {
		t.Fatalf("line 1 = %v, want ok with 5 added", first)
	}
	firstSeries := first["series"].([]interface{})
	if len(firstSeries) != 5 {
		t.Fatalf("line 1 series = %v, want 5 distinct identities", firstSeries)
	}
	one := findWireSeries(t, firstSeries, "cpu", map[string]interface{}{"a": "1", "b": "2"})
	if pts := one["points"].([]interface{}); len(pts) != 1 {
		t.Fatalf("two-label series points = %v", pts)
	}
	findWireSeries(t, firstSeries, "cpu", map[string]interface{}{"a": "b=2"})
	findWireSeries(t, firstSeries, "cpu", map[string]interface{}{"a": "b=2,c=3"})
	findWireSeries(t, firstSeries, "cpu", map[string]interface{}{"a:b": "c;d"})
	named := findWireSeries(t, firstSeries, "cpu:total{x=1}", map[string]interface{}{})
	if named["labels"] == nil {
		t.Fatal("unlabeled series must serialize labels as {}")
	}

	// 行 2：转义与乱序不改变身份，全部重复、不增加点，序列数仍为 5。
	second := decodeResultLine(t, got[1])
	if second["status"] != "ok" || second["added"].(float64) != 0 || second["duplicates"].(float64) != 5 {
		t.Fatalf("line 2 = %v, want 0 added and 5 duplicates", second)
	}
	if n := len(second["series"].([]interface{})); n != 5 {
		t.Fatalf("line 2 series count = %d, want 5", n)
	}
	// 转义书写解析回真实冒号/分号后仍只匹配原来那一条。
	findWireSeries(t, second["series"].([]interface{}), "cpu", map[string]interface{}{"a:b": "c;d"})

	// 行 3：整批失败，结构化冲突指出真实完整序列、时间戳与两个数值。
	bad := decodeResultLine(t, got[2])
	if bad["status"] != "error" || int(bad["line"].(float64)) != 3 || int(bad["index"].(float64)) != 2 {
		t.Fatalf("line 3 = %v, want error on input line 3 index 2", bad)
	}
	conflict := bad["conflict"].(map[string]interface{})
	if conflict["timestamp"].(float64) != 1000 ||
		conflict["existing"].(float64) != 1 || conflict["submitted"].(float64) != 9 {
		t.Fatalf("conflict detail = %v", conflict)
	}
	cSeries := conflict["series"].(map[string]interface{})
	if cSeries["name"] != "cpu" ||
		!reflect.DeepEqual(cSeries["labels"], map[string]interface{}{"a": "1", "b": "2"}) {
		t.Fatalf("conflict series = %v, want the real two-label identity", cSeries)
	}

	// 行 4：回滚后 cpu 仍是四条序列，各自一个点（时间戳 2000 的新增点未落盘）。
	full := decodeResultLine(t, got[3])
	fullArr := full["series"].([]interface{})
	if len(fullArr) != 4 {
		t.Fatalf("full cpu query = %v, want 4 series", fullArr)
	}
	for _, item := range fullArr {
		s := item.(map[string]interface{})
		if s["count"].(float64) != 1 || s["average"].(float64) != 1 {
			t.Fatalf("series %v must keep its own single point, got count=%v average=%v",
				s["labels"], s["count"], s["average"])
		}
	}

	// 行 5/6/7：子集匹配不被标签文本中的分隔符欺骗。
	q5 := decodeResultLine(t, got[4])["series"].([]interface{})
	if len(q5) != 1 || !reflect.DeepEqual(q5[0].(map[string]interface{})["labels"],
		map[string]interface{}{"a": "b=2"}) {
		t.Fatalf("a=b=2 subset = %v, want only the single-label series", q5)
	}
	q6 := decodeResultLine(t, got[5])["series"].([]interface{})
	if len(q6) != 1 || !reflect.DeepEqual(q6[0].(map[string]interface{})["labels"],
		map[string]interface{}{"a": "1", "b": "2"}) {
		t.Fatalf("b=2 subset = %v, want only the real two-label series", q6)
	}
	if q7 := decodeResultLine(t, got[6])["series"].([]interface{}); len(q7) != 0 {
		t.Fatalf("value fragment c=3 must not match as a label: %v", q7)
	}

	// 行 8：键与值中的 : ; 原样参与匹配。
	q8 := decodeResultLine(t, got[7])["series"].([]interface{})
	if len(q8) != 1 || !reflect.DeepEqual(q8[0].(map[string]interface{})["labels"],
		map[string]interface{}{"a:b": "c;d"}) {
		t.Fatalf("a:b=c;d subset = %v, want the delimiter-keyed series", q8)
	}

	// 行 9：指标名含分隔字符的序列按名字精确命中一条，且无标签。
	q9 := decodeResultLine(t, got[8])["series"].([]interface{})
	if len(q9) != 1 {
		t.Fatalf("delimiter-in-name query = %v, want 1 series", q9)
	}
	s9 := q9[0].(map[string]interface{})
	if s9["name"] != "cpu:total{x=1}" ||
		!reflect.DeepEqual(s9["labels"], map[string]interface{}{}) ||
		s9["count"].(float64) != 1 || s9["average"].(float64) != 1 {
		t.Fatalf("delimiter-in-name series = %v", s9)
	}
}

// Command darksafe is the 零信任身份与授权决策平台 entry point.
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// maxIngestLineBytes 是 ingest 单行内容的原始字节上限：64 MiB。
// 行分隔符 '\n' 不计入；内容恰好达到上限仍可进入写入或查询处理，只有超过才失败。
const maxIngestLineBytes = 64 * 1024 * 1024 // 67,108,864

func main() {
	command := "demo"
	if len(os.Args) > 1 {
		command = os.Args[1]
	}
	switch command {
	case "demo":
		runDemo()
	case "ingest":
		os.Exit(runIngest(os.Stdin, os.Stdout))
	case "version":
		fmt.Println("darksafe 0.1.0")
	case "help", "-h", "--help":
		usage(os.Stdout)
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage(os.Stderr)
		os.Exit(2)
	}
}

func usage(w io.Writer) {
	fmt.Fprintln(w, "usage: darksafe [demo|version|ingest|help]")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "commands:")
	fmt.Fprintln(w, "  demo     run the bundled access-decision demo")
	fmt.Fprintln(w, "  version  print the version")
	fmt.Fprintln(w, "  ingest   batch-ingest metric samples from standard input")
	fmt.Fprintln(w, "  help     show this help")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "ingest input:")
	fmt.Fprintln(w, "  Standard input is read line by line. Writes and queries may alternate;")
	fmt.Fprintln(w, "  queries only read data committed by earlier successful write lines and")
	fmt.Fprintln(w, "  never change storage. Blank lines produce no result but still count toward")
	fmt.Fprintln(w, "  line numbers. Accepted data is held in memory for this process only and is")
	fmt.Fprintln(w, "  never written to disk. A single line may contain at most 67,108,864 raw")
	fmt.Fprintln(w, "  bytes (64 MiB); the line separator is not counted, so a line of exactly")
	fmt.Fprintln(w, "  that length is still processed. A longer line always fails as one whole")
	fmt.Fprintln(w, "  line: it is never split into multiple inputs and even a valid JSON prefix")
	fmt.Fprintln(w, "  is never treated as a complete request, so it writes no points and runs no")
	fmt.Fprintln(w, "  query. It still produces one error result, data committed by earlier lines")
	fmt.Fprintln(w, "  is retained, and later lines continue to be processed in input order.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Write line: a JSON array of sample objects; each line is one batch.")
	fmt.Fprintln(w, "  A sample is {\"name\": string, \"timestamp\": <int64 milliseconds>,")
	fmt.Fprintln(w, "  \"value\": <finite number>} and may optionally include")
	fmt.Fprintln(w, "  \"labels\": {\"key\": \"value\"}. Empty label values are preserved verbatim;")
	fmt.Fprintln(w, "  omitting labels and passing an empty labels object both mean no labels.")
	fmt.Fprintln(w, "  Missing fields, wrong types, unknown fields, duplicate keys, illegal")
	fmt.Fprintln(w, "  numbers, or input that is not a JSON array fail the whole batch.")
	fmt.Fprintln(w, "  Duplicate keys are compared after JSON unescaping, so a field written")
	fmt.Fprintln(w, "  literally and the same field written with its first letter as a")
	fmt.Fprintln(w, "  \\uXXXX escape collide even when both values are identical; the same")
	fmt.Fprintln(w, "  rule applies to label keys and to query objects. The check is scoped to")
	fmt.Fprintln(w, "  a single object: fields in different samples, and a sample field sharing")
	fmt.Fprintln(w, "  a name with one of its own label keys, are both legal. A write failure")
	fmt.Fprintln(w, "  names the offending sample via its 1-based index and never carries a")
	fmt.Fprintln(w, "  conflict; a query failure carries neither index nor conflict.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Every string (metric names, label keys and label values, in both write")
	fmt.Fprintln(w, "  arrays and query objects) must be valid text: the raw bytes must be valid")
	fmt.Fprintln(w, "  UTF-8, and a \\uXXXX Unicode escape must denote a real character. A lone")
	fmt.Fprintln(w, "  high surrogate, a lone low surrogate, or a high surrogate not followed")
	fmt.Fprintln(w, "  immediately by a valid low surrogate is rejected; it is never repaired into")
	fmt.Fprintln(w, "  U+FFFD. (A backslash-escaped as \\\\uD800 is ordinary text, not an escape.)")
	fmt.Fprintln(w, "  Chinese text, supplementary-plane characters written literally or as a")
	fmt.Fprintln(w, "  matched surrogate pair, and a deliberately typed U+FFFD or \\uFFFD are all")
	fmt.Fprintln(w, "  valid. Corrupt text fails the whole line as a parse error with no index and")
	fmt.Fprintln(w, "  no conflict even if earlier samples in the array were valid: no point from")
	fmt.Fprintln(w, "  that line is committed and a corrupt query returns no matches. The error")
	fmt.Fprintln(w, "  distinguishes invalid UTF-8 bytes from invalid surrogate escapes.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  A series is identified by metric name plus its full label set; label order does")
	fmt.Fprintln(w, "  not matter. Submitting the same series/timestamp with the same value is a")
	fmt.Fprintln(w, "  duplicate (1 and 1.0 are equal) and is ignored; a different value rejects the")
	fmt.Fprintln(w, "  entire batch without overwriting anything. Any failure in a batch discards all")
	fmt.Fprintln(w, "  new points from that line; earlier successful batches remain in effect.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Query line: a JSON object {\"op\":\"query\",\"name\":\"cpu\",")
	fmt.Fprintln(w, "  \"start\":1000,\"end\":2000,\"labels\":{\"host\":\"a\"}}. op, name, start and")
	fmt.Fprintln(w, "  end are required; name is an exact, non-empty metric-name match and start/end")
	fmt.Fprintln(w, "  are inclusive int64 millisecond bounds (start == end queries that one")
	fmt.Fprintln(w, "  timestamp; start > end is rejected). labels is optional: omit it or pass {}")
	fmt.Fprintln(w, "  to match every series of the metric; otherwise every given key must exist with")
	fmt.Fprintln(w, "  exactly the same value (extra series labels are allowed, and an empty string")
	fmt.Fprintln(w, "  only matches a label that actually exists with that empty value). Names and")
	fmt.Fprintln(w, "  labels are matched verbatim without trimming or case folding.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "ingest output (one JSON line per non-empty input line, in input order):")
	fmt.Fprintln(w, "  write ok: {\"status\":\"ok\",\"added\":N,\"duplicates\":N,\"series\":[...]}")
	fmt.Fprintln(w, "           where every known series is listed with name, labels and timestamp-")
	fmt.Fprintln(w, "           sorted points; series are ordered by name and then by sorted labels.")
	fmt.Fprintln(w, "  query ok: {\"status\":\"ok\",\"op\":\"query\",\"series\":[{\"name\":...,")
	fmt.Fprintln(w, "           \"labels\":{},\"count\":N,\"average\":N.N}]} — one entry per series")
	fmt.Fprintln(w, "           having points in range, in the same series order, with the full name")
	fmt.Fprintln(w, "           and label set; an empty match yields []. The arithmetic mean is taken")
	fmt.Fprintln(w, "           over stored float64 values and is always finite for finite inputs.")
	fmt.Fprintln(w, "  failure: {\"status\":\"error\",\"line\":N,\"index\":M,\"error\":\"...\",")
	fmt.Fprintln(w, "           \"conflict\":{...}} — index is the 1-based sample position and is")
	fmt.Fprintln(w, "           omitted when the whole line cannot be parsed or for query lines;")
	fmt.Fprintln(w, "           conflict reports the series, timestamp, existing and submitted values.")
	fmt.Fprintln(w, "           An over-long line reports the size limit as a whole-line error with")
	fmt.Fprintln(w, "           no index and no conflict.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Processing continues after a failed line. The command exits non-zero if any")
	fmt.Fprintln(w, "  line failed, and zero when every line succeeded.")
}

// runIngest 逐行处理标准输入，逐行输出 JSON 结果。返回进程退出码。
func runIngest(in io.Reader, out io.Writer) int {
	store := darksafe.NewMetricStore()
	r := bufio.NewReaderSize(in, 64*1024)
	enc := json.NewEncoder(out)
	enc.SetEscapeHTML(false)

	exitCode := 0
	lineNo := 0
	for {
		line, err := readIngestLine(r)
		if err == io.EOF {
			return exitCode
		}
		if err != nil {
			fmt.Fprintln(os.Stderr, "ingest: read error:", err)
			return 1
		}
		lineNo++
		if line.tooLong {
			// 超长行从开头到下一个行分隔符都属于同一条失败输入：
			// 内容已整体排空，不解析、不写入任何点、不执行任何查询。
			lineErr := &darksafe.LineError{
				Status: "error",
				Line:   lineNo,
				Error: fmt.Sprintf("line exceeds the %d-byte (64 MiB) single-line size limit",
					maxIngestLineBytes),
			}
			if err := enc.Encode(lineErr); err != nil {
				fmt.Fprintln(os.Stderr, "ingest: write error:", err)
				return 1
			}
			exitCode = 1
			continue
		}
		if len(strings.TrimSpace(line.text)) == 0 {
			continue // 空白行不产生结果，但已计入行号
		}
		result, lineErr := store.ProcessLine(line.text)
		if lineErr != nil {
			lineErr.Line = lineNo
			if err := enc.Encode(lineErr); err != nil {
				fmt.Fprintln(os.Stderr, "ingest: write error:", err)
				return 1
			}
			exitCode = 1
			continue
		}
		if err := enc.Encode(result); err != nil {
			fmt.Fprintln(os.Stderr, "ingest: write error:", err)
			return 1
		}
	}
}

// ingestLine 是读到的一行内容，不含结尾的 '\n' 分隔符（分隔符不计入行大小）。
// tooLong 为 true 时表示该行内容超过 maxIngestLineBytes，text 不保留其内容；
// 该行从开头到下一个 '\n' 的全部字节都已被排空，不会拆成多条输入。
type ingestLine struct {
	text    string
	tooLong bool
}

// readIngestLine 读取下一行输入。沿用 bufio.Scanner 的换行识别方式：
// 以 '\n' 分隔，结尾的 '\n' 不属于行内容（"foo\r\n" 的内容仍为 "foo\r"，
// 因此空白判定与现有行为一致）。行内容不超过上限时累积到 text；
// 一旦超过上限，停止累积并继续排空到下一个 '\n' 或输入结束，返回 tooLong。
// 输入直接结束且没有任何字节时返回 io.EOF；超长行在末尾无换行结束时
// 同样作为一条失败行返回，下一次调用才返回 io.EOF，不会丢失或重复。
// 除 io.EOF 外的非空 error 均为底层输入读取故障，调用方应终止处理。
func readIngestLine(r *bufio.Reader) (ingestLine, error) {
	var b strings.Builder
	size := 0
	tooLong := false
	for {
		chunk, err := r.ReadSlice('\n')
		if len(chunk) > 0 {
			if chunk[len(chunk)-1] == '\n' {
				chunk = chunk[:len(chunk)-1]
			}
			size += len(chunk)
			if size > maxIngestLineBytes {
				tooLong = true
				b = strings.Builder{} // 内容已注定失败，排空后续片段时不再保留此前累积
			}
			if !tooLong {
				b.Write(chunk)
			}
		}
		switch err {
		case nil:
			if tooLong {
				return ingestLine{tooLong: true}, nil
			}
			return ingestLine{text: b.String()}, nil
		case bufio.ErrBufferFull:
			// 行尚未结束且本次缓冲已耗尽，继续读取后续片段。
			continue
		case io.EOF:
			// 最后一行没有结尾换行；完全没有读到字节才表示输入结束，
			// 否则最后一行（含超长行）在本次返回，下次调用才得到 io.EOF。
			if size == 0 {
				return ingestLine{}, io.EOF
			}
			if tooLong {
				return ingestLine{tooLong: true}, nil
			}
			return ingestLine{text: b.String()}, nil
		default:
			return ingestLine{}, err
		}
	}
}

func runDemo() {
	subjects := []darksafe.Subject{
		{ID: "u-1001", Kind: "user", Roles: []string{"org/payments/ledger:read"}},
		{ID: "svc-batch", Kind: "service", Roles: []string{"owner"}},
		{ID: "u-1002", Kind: "user", Disabled: true},
	}
	resource := darksafe.Resource{ID: "ledger-main", Scope: "org/payments/ledger"}
	allowed := 0
	for _, subject := range subjects {
		decision := darksafe.Access(subject, resource, "read")
		if decision.Allowed {
			allowed++
		}
		fmt.Printf("subject=%s allowed=%v reason=%s\n", subject.ID, decision.Allowed, decision.Reason)
	}
	fmt.Printf("summary: %d of %d subjects allowed\n", allowed, len(subjects))
}

